// Generated by `just generate` from `src/plugins/claudetto/slices/decide/domain/ask.ts`. Edit the source and run `just generate`.
// The pick of Jev for an `AskUserQuestion` call: the request for the questions, and the questions with the pick added.
// A facts question is one that the question and the option texts alone settle.
// A project question depends on a file or the session, which Jev does not get, so it stays as it is.
// A facts question gets the pick of Jev in the description of the picked option, when Jev is sure: the pick beats chance by `MIN_MARGIN`.
// A preference question, a multi-select question, and a question with fewer than 2 options stay as they are.
// The question text stays as Claude sent it, because the answers come back keyed by that text.

import { MIN_CONFIDENCE, MIN_MARGIN, MIN_OPTIONS } from "../limits.ts";
import {
  ASK_KIND,
  ASK_KIND_FACTS,
  ASK_KIND_PREFERENCE,
  ASK_KIND_PROJECT,
  ASK_NOTE,
  ASK_PICK,
} from "../prompts.ts";
import type { Answer } from "./request.ts";

const KIND = {
  type: "choice",
  instructions: ASK_KIND,
  criteria: {
    preference: ASK_KIND_PREFERENCE,
    facts: ASK_KIND_FACTS,
    project: ASK_KIND_PROJECT,
  },
};

/** One option of an `AskUserQuestion` question. */
export interface AskOption {
  readonly label: string;
  readonly description?: string;
}

/** One question of an `AskUserQuestion` call. */
export interface AskQuestion {
  readonly question: string;
  readonly multiSelect?: boolean;
  readonly options?: readonly AskOption[];
}

/** The answers of Jev by key, `kind_<i>` for the kind of question `i` and `pick_<i>` for its pick. */
export type AskAnswers = Record<string, Answer | undefined>;

/** The request of `ask` for the questions: the state and the questions of the API, or `null` when no question needs Jev. */
export const askRequest = (
  questions: readonly AskQuestion[],
): { state: string; questions: Record<string, unknown> } | null => {
  const asked: Record<string, unknown> = {};
  const state: string[] = [];
  questions.forEach((q, i) => {
    const options = q.options ?? [];
    if (options.length < MIN_OPTIONS || q.multiSelect) return;
    state.push(
      `Question ${i}: ${q.question}`,
      ...options.map((o) => `- ${o.label}: ${o.description ?? ""}`),
    );
    asked[`kind_${i}`] = {
      ...KIND,
      instructions: `${KIND.instructions} (question ${i})`,
    };
    asked[`pick_${i}`] = {
      type: "choice",
      instructions: ASK_PICK({ index: String(i) }),
      criteria: Object.fromEntries(
        options.map((o) => [o.label, o.description || o.label]),
      ),
    };
  });
  return Object.keys(asked).length
    ? { state: state.join("\n"), questions: asked }
    : null;
};

/** The questions with the pick of Jev in the picked option of each facts question, and the other fields kept. */
export const withPicks = <Q extends AskQuestion>(
  questions: readonly Q[],
  answers: AskAnswers,
): Q[] =>
  questions.map((q, i) => {
    const kind = answers[`kind_${i}`];
    const pick = answers[`pick_${i}`];
    if (
      q.multiSelect ||
      kind?.choice !== "facts" ||
      !(kind.confidence >= MIN_CONFIDENCE) ||
      pick === undefined ||
      !(
        pick.confidence >=
        Math.max(MIN_CONFIDENCE, 1 / (q.options ?? []).length + MIN_MARGIN)
      ) ||
      !(q.options ?? []).some((o) => o.label === pick.choice)
    )
      return q;
    const note = ASK_NOTE({ confidence: pick.confidence.toFixed(2) });
    return {
      ...q,
      options: (q.options ?? []).map((o) =>
        o.label === pick.choice
          ? {
              ...o,
              description: o.description ? `${o.description} ${note}` : note,
            }
          : o,
      ),
    };
  });

const asAnswer = (value: unknown): Answer | undefined => {
  if (typeof value !== "object" || value === null) return undefined;
  const { choice, confidence } = value as Record<string, unknown>;
  if (typeof choice !== "string") return undefined;
  if (typeof confidence !== "number" || !(confidence >= 0 && confidence <= 1))
    return undefined;
  return { choice, confidence };
};

/** The answers of `ask` from its JSON output. An entry that is not an answer is `undefined`, so its question stays as asked. */
export const parseAskAnswers = (stdout: string): AskAnswers | undefined => {
  let value: unknown;
  try {
    value = JSON.parse(stdout);
  } catch {
    return undefined;
  }
  if (typeof value !== "object" || value === null || Array.isArray(value))
    return undefined;
  return Object.fromEntries(
    Object.entries(value).map(([key, v]) => [key, asAnswer(v)]),
  );
};
